// Package pricing holds list prices for the clouds a cluster may run on today (AWS, Azure) and for UpCloud.
// The JSON files in data/ are generated by tools/pricegen from the providers' own price APIs and embedded at build time,
// so the analyzer never needs cloud credentials or internet access inside the cluster.
package pricing

import (
	"embed"
	"encoding/json"
	"fmt"
	"slices"
	"sort"
	"strings"
)

// HoursPerMonth is the usual cloud billing month (365 * 24 / 12).
const HoursPerMonth = 730.0

// Cloud is the price list of one current provider (AWS, Azure), in its billing currency.
type Cloud struct {
	Provider  string             `json:"provider"`
	Currency  string             `json:"currency"`
	Generated string             `json:"generated"`
	Source    string             `json:"source"`
	Regions   map[string]*Region `json:"regions"`
}

// Region prices. Missing values are 0 and are reported as "not priced" rather than guessed.
type Region struct {
	Instances          map[string]float64 `json:"instances"`                    // instance type -> on-demand price per hour (Linux)
	StorageGBMonth     map[string]float64 `json:"storageGBMonth,omitempty"`     // volume type (gp3, gp2, ...) -> price per GB-month
	ControlPlaneHourly float64            `json:"controlPlaneHourly,omitempty"` // managed Kubernetes fee per cluster-hour
	LoadBalancerHourly float64            `json:"loadBalancerHourly,omitempty"` // one network load balancer, hourly part only
}

// UpCloud is the UpCloud price list in EUR.
type UpCloud struct {
	Currency  string                  `json:"currency"`
	Generated string                  `json:"generated"`
	Source    string                  `json:"source"`
	Zones     map[string]*UpCloudZone `json:"zones"`
}

type UpCloudZone struct {
	Plans                []Plan             `json:"plans"`
	StorageMaxIOPSMonth  float64            `json:"storageMaxiopsGBMonth"` // per GB-month
	StorageStandardMonth float64            `json:"storageStandardGBMonth,omitempty"`
	LoadBalancerMonthly  float64            `json:"loadBalancerMonthly,omitempty"` // managed load balancer plan used in estimates
	ControlPlaneMonthly  float64            `json:"controlPlaneMonthly,omitempty"` // managed Kubernetes (UKS) control plane used in estimates
	LoadBalancerPlans    map[string]float64 `json:"loadBalancerPlans,omitempty"`   // all managed load balancer plans, per month
	KubernetesPlans      map[string]float64 `json:"kubernetesPlans,omitempty"`     // all UKS control plane plans, per month
}

// Plan is one UpCloud Cloud Server plan.
type Plan struct {
	Name      string  `json:"name"`
	Cores     int     `json:"cores"`
	MemoryMiB int     `json:"memoryMiB"`
	StorageGB int     `json:"storageGB"`
	Monthly   float64 `json:"monthly"`
}

// FX holds exchange rates as units of currency per 1 EUR (ECB reference rates).
type FX struct {
	Date  string             `json:"date"`
	Rates map[string]float64 `json:"rates"`
}

//go:embed data/*.json
var files embed.FS

// Book is everything the estimator needs, loaded from the embedded files.
type Book struct {
	Clouds  map[string]*Cloud // provider id (aws, azure) -> prices
	UpCloud *UpCloud
	FX      *FX
}

// Load reads the embedded price data.
func Load() (*Book, error) {
	b := &Book{Clouds: map[string]*Cloud{}}
	for _, p := range []string{"aws", "azure"} {
		c := &Cloud{}
		if err := read("data/"+p+".json", c); err != nil {
			return nil, err
		}
		b.Clouds[p] = c
	}
	b.UpCloud = &UpCloud{}
	if err := read("data/upcloud.json", b.UpCloud); err != nil {
		return nil, err
	}
	b.FX = &FX{}
	if err := read("data/fx.json", b.FX); err != nil {
		return nil, err
	}
	return b, nil
}

func read(name string, v any) error {
	raw, err := files.ReadFile(name)
	if err != nil {
		return err
	}
	if err := json.Unmarshal(raw, v); err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	return nil
}

// ToEUR converts an amount in currency cur to EUR. ok is false for an unknown currency.
func (f *FX) ToEUR(amount float64, cur string) (float64, bool) {
	if strings.EqualFold(cur, "EUR") {
		return amount, true
	}
	r := f.Rates[strings.ToUpper(cur)]
	if r == 0 {
		return 0, false
	}
	return amount / r, true
}

// Family is the plan family: the upper-case prefix (DEV, STARTER, PREMIUM, HICPU, HIMEM, CLOUDNATIVE)
// or "general" for General Purpose plans, which have none (2xCPU-4GB).
func (p Plan) Family() string {
	if prefix, _, ok := strings.Cut(p.Name, "-"); ok && prefix != "" && prefix == strings.ToUpper(prefix) && !strings.ContainsAny(prefix[:1], "0123456789") {
		return prefix
	}
	return "general"
}

// Zone returns the UpCloud zone's prices, keeping only plans of the given families (all when none are given),
// sorted cheapest first.
func (u *UpCloud) Zone(name string, families ...string) (*UpCloudZone, error) {
	src := u.Zones[name]
	var z *UpCloudZone
	if src != nil {
		cp := *src
		cp.Plans = nil
		for _, p := range src.Plans {
			if len(families) == 0 || slices.ContainsFunc(families, func(f string) bool { return strings.EqualFold(f, p.Family()) }) {
				cp.Plans = append(cp.Plans, p)
			}
		}
		z = &cp
	}
	if z == nil || len(z.Plans) == 0 {
		names := make([]string, 0, len(u.Zones))
		for n := range u.Zones {
			names = append(names, n)
		}
		sort.Strings(names)
		return nil, fmt.Errorf("no UpCloud prices for zone %q (known: %s)", name, strings.Join(names, ", "))
	}
	sort.SliceStable(z.Plans, func(i, j int) bool { return z.Plans[i].Monthly < z.Plans[j].Monthly })
	return z, nil
}
